package com.rationportal.controller; import com.rationportal.model.Grievance; import com.rationportal.repository.GrievanceRepository; import org.springframework.http.ResponseEntity; import org.springframework.lang.NonNull; import org.springframework.web.bind.annotation.*; import java.util.List; import java.util.UUID; @RestController @RequestMapping("/api/grievances") public class GrievanceController { private final GrievanceRepository repository; public GrievanceController(GrievanceRepository repository){this.repository=repository;} @PostMapping public Grievance submit(@RequestBody @NonNull Grievance grievance){if(grievance.getGrievanceNumber()==null||grievance.getGrievanceNumber().isBlank()){grievance.setGrievanceNumber("GRV"+UUID.randomUUID().toString().replace("-","").substring(0,8).toUpperCase());}return repository.save(grievance);} @GetMapping public List<Grievance> getAll(){return repository.findAll();} @GetMapping("/{number}") public ResponseEntity<Grievance> getByNumber(@PathVariable @NonNull String number){return repository.findByGrievanceNumber(number).map(ResponseEntity::ok).orElse(ResponseEntity.notFound().build());} }
